// Progress for a bulk job lives in one Redis hash. HINCRBY is atomic, so any
// number of consumers can report results concurrently without a
// read-modify-write race — the counts stay correct under load.
type ProgressTracker struct {
    rdb *redis.Client
    ttl time.Duration
}

func (p *ProgressTracker) key(jobID string) string {
    return "job:" + jobID + ":progress"
}

// Seed every counter up front so a new job reports 0/N instead of an empty
// hash, which a client can't tell apart from a job that doesn't exist.
func (p *ProgressTracker) Init(ctx context.Context, jobID string, total int) error {
    pipe := p.rdb.TxPipeline()
    pipe.HSet(ctx, p.key(jobID), map[string]any{
        "total": total, "queued": total,
        "processing": 0, "succeeded": 0, "failed": 0,
    })
    pipe.Expire(ctx, p.key(jobID), p.ttl)
    _, err := pipe.Exec(ctx)
    return err
}

// Settle moves one item out of "processing" into its terminal state. Both
// counters move inside one MULTI so a crash can't leave them disagreeing.
func (p *ProgressTracker) Settle(ctx context.Context, jobID string, ok bool) error {
    outcome := "failed"
    if ok {
        outcome = "succeeded"
    }
    pipe := p.rdb.TxPipeline()
    pipe.HIncrBy(ctx, p.key(jobID), "processing", -1)
    pipe.HIncrBy(ctx, p.key(jobID), outcome, 1)
    _, err := pipe.Exec(ctx)
    return err
}

// The proxied request must never wait on logging. Events go into a buffered
// channel; when it's full we drop and count instead of adding latency to the
// caller. A dropped log is cheaper than a slow gateway.
type AccessLogger struct {
    events  chan Event
    dropped atomic.Uint64
}

func (l *AccessLogger) Record(e Event) {
    select {
    case l.events <- e:
    default:
        l.dropped.Add(1) // exported as a metric, never backpressures the hot path
    }
}

// Batch so Kafka sees far fewer, larger writes than there are requests.
// Flush on whichever comes first: a full batch or the ticker.
func (l *AccessLogger) Run(ctx context.Context, w *kafka.Writer) {
    batch := make([]kafka.Message, 0, batchSize)
    tick := time.NewTicker(flushInterval)
    defer tick.Stop()

    flush := func() {
        if len(batch) == 0 {
            return
        }
        if err := w.WriteMessages(ctx, batch...); err != nil {
            l.dropped.Add(uint64(len(batch)))
        }
        batch = batch[:0]
    }

    for {
        select {
        case e := <-l.events:
            if batch = append(batch, e.Message()); len(batch) >= batchSize {
                flush()
            }
        case <-tick.C:
            flush()
        case <-ctx.Done():
            flush()
            return
        }
    }
}
